'use strict';
const $ = s => document.querySelector(s);
const esc = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon = (name,cls='') => `<svg class="icon ${cls}" aria-hidden="true"><use href="assets/icons.svg#${name}"/></svg>`;
const places = [
 {name:'체육관 입구',sub:'공연장으로 가는 길',ids:['A1','A2'],person:'서우'},
 {name:'운영본부',sub:'축제 운영과 안내',ids:['B1','B2'],person:'라온'},
 {name:'홍보부스',sub:'축제 홍보와 사진 촬영',ids:['C1','C2'],person:'도윤'}
];
const clues = {
 A1:{title:'행사장 지도',type:'공간 기록',icon:'map-trifold',place:0,heading:'공연장으로 가는 길',kind:'map'},
 A2:{title:'대화 기록',type:'서우와 운영진의 대화',icon:'chat-circle-text',place:0,heading:'가고 싶은데,\n갈 수 있는 길이 없어.',kind:'chat',messages:[['서우','공연을 보러 가고 싶어. 휠체어로 갈 수 있는 길이 있을까?'],['운영진','다들 이 계단으로 올라가. 따로 마련한 길은 없어.'],['서우','그럼 나는 공연장에 어떻게 들어가지?']]},
 B1:{title:'진행팀 모집 안내',type:'운영본부 게시물',icon:'megaphone',place:1,heading:'진행팀을 모집합니다.',kind:'notice'},
 B2:{title:'지원 상담 기록',type:'라온과 담당자의 대화',icon:'chat-circle-text',place:1,heading:'보여 줄 기회도\n없는 걸까?',kind:'chat',messages:[['라온','말이 조금 느리지만 대본을 연습했어요. 친구와 함께 진행하면 할 수 있어요.'],['담당자','연습은 확인하지 않을게. 한국어가 서툴면 진행팀은 안 돼.'],['라온','내가 할 수 있는지 보여 줄 기회도 없네요.']]},
 C1:{title:'홍보 채팅',type:'홍보팀 대화',icon:'chat-circle-text',place:2,heading:'사진을 찍었다면,\n올려도 괜찮을까?',kind:'chat',messages:[['홍보 담당','도윤이 넘어지는 사진, 표정이 재미있어서 축제 홍보 게시판에 올렸어.'],['친구','도윤한테 올려도 되는지 물었어?'],['홍보 담당','아니. 내가 찍은 사진이잖아.']]},
 C2:{title:'도윤의 메시지',type:'당사자가 남긴 이야기',icon:'note-pencil',place:2,heading:'내가 원한 사진은\n아니었어.',kind:'memo'}
};
const problems=['시설 때문에 동등한 참여가 막힘','언어를 이유로 기회를 일괄 제한함','동의 없이 사진을 공개함','참여하고 싶은 마음이 없음'];
const hints=['서우는 공연을 보고 싶어 해. 이동 경로를 살펴봐.','연습을 확인하기도 전에 지원을 막은 기준이 무엇인지 살펴봐.','사진을 찍은 사람과 사진에 나온 사람의 동의는 별개야. 공개 전에 무엇을 확인했을까?'];
const explanations=['참여 의지가 아니라 접근 가능한 길이 없는 시설이 문제야.','역할 수행에 필요한 조건을 살피지 않고 언어만으로 기회를 막은 규칙이 문제야.','본인의 동의 없이 사진을 공개하고 삭제 요청 뒤에도 남겨 둔 행동이 문제야.'];
const fresh = () => ({screen:'intro',read:new Set(),place:0,clue:'A1',returnTo:'place',person:0,selections:[[],[],[]],answers:[null,null,null],solved:[false,false,false],feedback:null,proposalPerson:0,proposal:'',error:'',expanded:false,result:null});
let state=fresh();
function announce(message){$('#live').textContent='';setTimeout(()=>$('#live').textContent=message,30)}
function go(screen){state.screen=screen;state.feedback=null;state.error='';render();window.scrollTo(0,0);$('#main')?.focus({preventScroll:true})}
function header(title,back,meta=''){return `<header class="topbar">${back?`<button class="icon-button" data-action="${back}" aria-label="뒤로 가기">${icon('caret-left')}</button>`:icon('notebook')}<strong>${title}</strong>${meta?`<span class="meta">${meta}</span>`:''}<button class="icon-button" data-action="help" aria-label="활동 안내">${icon('question')}</button></header>`}
function bottom(content){return `<footer class="bottom">${content}</footer>`}
function primary(text,action,disabled=false){return `<button class="primary" data-action="${action}" ${disabled?'disabled':''}>${text}${!disabled?icon('arrow-right'):''}</button>`}
function nav(active){return `<nav class="bottom bottom-tabs" aria-label="조사 메뉴">${[['map','map-trifold','조사 지도'],['archive','files','단서함']].map(([s,i,l])=>`<button class="tab ${active===s?'active':''}" data-action="nav" data-screen="${s}" ${active===s?'aria-current="page"':''}>${icon(i)}${l}</button>`).join('')}</nav>`}
function layout(head,content,foot){return `${head}<main id="main" tabindex="-1" class="fade-in">${content}</main>${foot||''}`}
function personTabs(selected,action){return `<div class="person-tabs" role="group" aria-label="사연 선택">${places.map((p,i)=>`<button class="person-tab ${selected===i?'active':''}" data-action="${action}" data-index="${i}" aria-pressed="${selected===i}">${p.person}${state.solved[i]?icon('check'):''}</button>`).join('')}</div>`}
function count(p){return p.ids.filter(id=>state.read.has(id)).length}
function clueRow(id,openAction='open-clue'){const c=clues[id],p=places[c.place],locked=id===p.ids[1]&&!state.read.has(p.ids[0]);return `<button class="clue-row" data-action="${openAction}" data-id="${id}" ${locked?'disabled':''}><span class="stamp">${id}</span><span class="clue-info"><b>${c.title}</b><small>${locked?'앞의 단서를 먼저 읽어 줘':c.type}</small></span>${locked?icon('lock-simple'):state.read.has(id)?`<span class="read-badge">${icon('check')}읽음</span>`:icon('caret-right')}</button>`}
function routeMap(){return `<figure class="exhibit-map"><svg viewBox="0 0 310 225" role="img" aria-label="체육관 2층 공연장으로 가는 유일한 길은 계단 12칸이며 엘리베이터, 경사로, 다른 출입로는 없습니다."><rect x="18" y="18" width="188" height="91" rx="2" fill="#e3e2d2" stroke="#8e9b84"/><rect x="29" y="29" width="166" height="69" fill="#eeecdf" stroke="#8e9b84"/><text x="111" y="57" text-anchor="middle" font-size="15" fill="#384e3e">체육관 2층</text><text x="111" y="80" text-anchor="middle" font-size="12" fill="#64755a">공연장</text><path d="M212 43h48v90h-48Z" fill="#e8decb" stroke="#a7987c"/>${Array.from({length:11},(_,i)=>`<path d="M212 ${50+i*7}h48" stroke="#b4a58b"/>`).join('')}<text x="236" y="154" text-anchor="middle" font-size="12" fill="#846343">계단 12칸</text><rect x="18" y="167" width="155" height="42" fill="#dbe2cf" stroke="#a4b396"/><text x="96" y="193" text-anchor="middle" font-size="13" fill="#516448">운동장</text><path d="M183 202H284V119H266" fill="none" stroke="#b17d50" stroke-width="2" stroke-dasharray="5 5"/><circle cx="184" cy="202" r="4" fill="#b17d50"/><path d="m272 113-7 6 7 6" stroke="#b17d50" fill="none" stroke-width="2"/></svg><figcaption>엘리베이터 · 경사로 · 다른 출입로 없음</figcaption></figure>`}
function material(id){const c=clues[id];if(c.kind==='map')return routeMap();if(c.kind==='notice')return `<article class="paper"><div class="material-type">FESTIVAL / 운영본부</div><h2>진행팀 모집 안내</h2><div class="paper-rule"></div><p>한국어가 서툰 학생은 진행 역할에 지원할 수 없습니다.</p><p style="margin-top:14px">다른 부스의 손님으로 참여해 주세요.</p><div class="footer">※ 사건 속 가상의 안내문입니다.</div></article>`;if(c.kind==='memo')return `<article class="memo"><p>사진을 올려도 된다고 한 적 없어. 내려 달라고 했는데 아직 그대로야. 친구들이 그 사진 얘기를 해서 축제에 가기가 불편해.</p><div class="signature">도윤이 남긴 메시지</div></article>`;return `<div class="chat">${c.messages.map(([name,text],i)=>`<div class="chat-item ${i%2?'other':''}"><span class="avatar">${name[0]}</span><div><div class="chat-name">${name}</div><p class="bubble">${text}</p></div></div>`).join('')}</div>${id==='C1'?'<p class="subtle">이 기록에는 사진을 공개했다는 사실만 담겨 있어요.</p>':''}`}
function miniature(id){const c=clues[id];return `<div class="miniature ${c.kind==='chat'?'chat-mini':''}" aria-hidden="true">${icon(c.icon)}<span class="mini-line"></span><span class="mini-line short"></span></div>`}
function intro(){return layout(header('학교 축제 조사 수첩'),`<section class="intro"><div class="eyebrow">모두가 함께하는 축제를 위해</div><h1>같은 축제,<br>서로 다른 이야기.</h1><p class="lead">축제를 기다리던 세 친구는<br>왜 참여를 망설이고 있을까?</p><div class="intro-art"><img src="assets/campus.png" alt="체육관과 축제 부스가 있는 학교 전경"><span class="art-caption">우리 학교 · 축제 당일</span></div><div class="people-line"><span class="avatar">서</span><span class="avatar apricot">라</span><span class="avatar blue">도</span><p>서우 · 라온 · 도윤의 이야기를 찾아보자.</p></div><p>단서 여섯 개를 모으고, 무엇이 참여를 막았는지 밝혀 줘. 마지막에는 우리 모둠의 해결책을 남길 거야.</p><section class="section"><div class="section-title"><h2>함께 조사하는 방법</h2><small>2~4명 · 약 25분</small></div><div class="roles"><div class="role">${icon('hand-tap')}<b>조작하기</b><small>화면을 열고<br>선택해요</small></div><div class="role">${icon('magnifying-glass')}<b>증거 확인</b><small>단서를 읽고<br>비교해요</small></div><div class="role">${icon('chat-circle-text')}<b>의견 제시</b><small>생각과 근거를<br>나눠요</small></div></div><p class="note">장소를 바꿀 때 역할도 바꿔 줘. 2명은 증거 확인과 의견 제시를 함께, 4명은 두 사람이 의견 제시를 맡아.</p></section><div class="privacy">${icon('info')}<span>새로고침하거나 창을 닫으면 진행 내용과 답변이 사라져요. 모든 인물과 사건은 창작입니다.</span></div></section>`,bottom(primary('조사 시작','start')))}
function mapScreen(){const n=state.read.size;return layout(header('축제 조사',null,`단서 ${n}/6`),`<h1>어디부터 살펴볼까?</h1><p class="lead">세 장소에서 친구들의 이야기를 찾아보자.</p><div class="map"><img src="assets/campus.png" alt="축제 장소 지도. 체육관 입구, 운영본부, 홍보부스를 선택할 수 있어요.">${places.map((p,i)=>`<button class="map-pin p${i} ${count(p)===2?'done':''}" data-action="place" data-index="${i}">${icon(count(p)===2?'check-circle':'map-pin')}${p.name}</button>`).join('')}<span class="map-key">FESTIVAL FIELD MAP</span></div><div class="place-list">${places.map((p,i)=>`<button class="place-row ${count(p)===2?'done':''}" data-action="place" data-index="${i}">${icon(count(p)===2?'check-circle':'map-pin')}<span class="place-info"><b>${p.name}</b><small>${p.sub}</small></span><span class="count">${count(p)}/2</span>${icon('caret-right','chevron')}</button>`).join('')}</div><div class="step-hint">${icon('users')}<span>새로운 장소에서는 조작·증거 확인·의견 제시 역할을 바꿔 줘.</span></div><div class="go-reason">${primary(n===6?'단서를 모았어, 추리하러 가기':`단서 ${6-n}개를 더 찾아보자`,'reason',n!==6)}</div>`,nav('map'))}
function placeScreen(){const p=places[state.place];return layout(header(p.name,'back-map',`${count(p)}/2`),`<div class="eyebrow">조사 장소 ${String(state.place+1).padStart(2,'0')}</div><h1>${p.name}에서<br>찾은 이야기</h1><p class="lead">기록을 하나씩 열어 살펴보자.<br>서로의 생각도 함께 나눠 줘.</p><div class="progress-line"><span style="width:${count(p)*50}%"></span></div>${p.ids.map(id=>clueRow(id)).join('')}<div class="step-hint">${icon('magnifying-glass')}<span>무슨 일이 있었는지, 당사자는 어떤 마음인지 살펴봐.</span></div>`,bottom(primary(count(p)===2?'다른 장소 살펴보기':'조사 지도로','back-map')))}
function clueScreen(){const c=clues[state.clue],p=places[c.place],other=p.ids.find(id=>id!==state.clue);return layout(header(p.name,'back-clue',state.clue),`<div class="eyebrow">${state.clue} · ${c.title}</div><h1>${c.heading.replace('\n','<br>')}</h1><p class="lead">${c.type}</p>${material(state.clue)}${state.read.has(other)?`<section class="related"><h3>함께 살펴보기</h3>${clueRow(other,'related')}</section>`:''}`,bottom(primary(state.read.has(state.clue)?'확인했어요':'읽었어요','mark-read')))}
function archiveScreen(){return layout(header('단서함',null,`${state.read.size}/6`),`<div class="eyebrow">수집한 기록</div><h1>작은 단서들을<br>다시 이어 보자.</h1><p class="lead">읽은 단서는 언제든 다시 볼 수 있어.</p>${places.map((p,i)=>`<div class="archive-head"><h2>${p.name}</h2><small>${count(p)}/2</small></div>${p.ids.map(id=>state.read.has(id)?clueRow(id):`<button class="clue-row" data-action="place" data-index="${i}"><span class="stamp">${id}</span><span class="clue-info"><b>아직 찾지 못한 단서</b><small>${p.name}에서 찾아보기</small></span>${icon('arrow-right')}</button>`).join('')}`).join('')}<div class="section">${primary('추리 정리로','reason',state.read.size!==6)}</div>`,nav('archive'))}
function reasonScreen(){const p=state.person,selected=state.selections[p],ids=state.expanded?Object.keys(clues):[...new Set([...selected,...places[p].ids])];const all=state.solved.every(Boolean);const f=state.feedback;return layout(header('추리 정리','back-map',`${state.solved.filter(Boolean).length}/3 해결`),`${personTabs(p,'person')}<h1>무엇이 참여를<br>막았을까?</h1><p class="question-sub">${places[p].person}의 사연을 증거로 설명해 보자.</p><section class="section"><div class="section-title"><h2>증거 두 개를 골라 줘</h2><small>${selected.length}/2 선택</small></div><div class="evidence-grid">${ids.map(id=>`<div class="evidence-card ${selected.includes(id)?'selected':''}"><button class="evidence-select" data-action="select-evidence" data-id="${id}" aria-pressed="${selected.includes(id)}">${miniature(id)}<span class="selection-mark">${selected.includes(id)?icon('check'):''}</span><b>${id} ${clues[id].title}</b><small>${places[clues[id].place].name}</small></button><button class="preview-button" data-action="preview" data-id="${id}" aria-label="${id} ${clues[id].title} 원문 보기">원문 보기 ↗</button></div>`).join('')}</div><button class="text-button" data-action="expand">${state.expanded?'단서 접기':'다른 단서도 비교하기'} ${icon(state.expanded?'caret-up':'caret-down')}</button></section><section class="section"><div class="section-title"><h2>어떤 문제와 연결될까?</h2></div><div class="answers" role="radiogroup" aria-label="인권 문제">${problems.map((text,i)=>`<button class="answer" role="radio" aria-checked="${state.answers[p]===i}" data-action="answer" data-index="${i}"><span class="radio" aria-hidden="true"></span><span>${text}</span></button>`).join('')}</div></section>${f?`<div class="feedback ${f.correct?'correct':''}" role="status"><b>${icon(f.correct?'check-circle':'magnifying-glass')}${f.correct?'증거가 연결됐어':'조금 더 살펴보자'}</b>${esc(f.message)}</div>`:''}${state.solved[p]&&!f?`<div class="solved">${icon('check-circle')}이 사연의 증거를 연결했어.</div>`:''}`,bottom(primary(all?'우리 모둠의 해결책 쓰기':state.solved[p]?'다음 사연 살펴보기':'연결 확인',all?'write':state.solved[p]?'next-person':'check')))}
function writeScreen(){const p=state.proposalPerson;return layout(header('해결 제안','back-reason'),`<div class="eyebrow">우리 모둠의 한 걸음</div><h1>이제, 함께할 수 있는<br>축제로 바꿔 보자.</h1><p class="lead">한 사람의 사연을 골라 해결책을 남겨 줘.</p><section class="section">${personTabs(p,'proposal-person')}<div class="paper" style="margin-top:0"><div class="material-type">${places[p].person}의 사연</div><h3>${problems[p]}</h3><div class="compact-evidence">${places[p].ids.map(id=>`<span class="pill">${id} ${clues[id].title}</span>`).join('')}</div></div></section><section class="section"><label class="writing-question" for="proposal">누가 무엇을 어떻게 바꾸면<br>이 친구도 참여할 수 있을까?</label><textarea id="proposal" maxlength="300" placeholder="우리 모둠의 해결책을 한두 문장으로 적어 줘." aria-describedby="writing-note char-count${state.error?' write-error':''}" ${state.error?'aria-invalid="true"':''}>${esc(state.proposal)}</textarea><div class="counter" id="char-count">${state.proposal.length}/300</div>${state.error?`<p class="error-text" id="write-error" role="alert">${state.error}</p>`:''}<p class="note" id="writing-note">실제 친구의 이름이나 개인적인 경험은 쓰지 않아도 돼. 정해진 답보다 구체적으로 바꿀 수 있는 방법을 생각해 봐.</p></section><div class="privacy">${icon('info')}<span>답변은 서버에 제출되지 않아요. 결과 화면을 보며 발표해 주세요.</span></div>`,bottom(primary('활동 마치기','finish')))}
function resultScreen(){const r=state.result;return layout(header('우리 모둠의 기록',null),`<section class="result-heading">${icon('check-circle')}<div class="eyebrow">조사 완료</div><h1>함께할 축제의<br>첫 단서를 찾았어.</h1><p>우리 모둠의 제안을 친구들과 나눠 보자.</p></section><article class="result-paper"><div class="eyebrow">FESTIVAL / FIELD NOTES</div><div class="result-label">우리가 살펴본 사연</div><h2>${r.person}의 이야기</h2><section class="result-section"><div class="result-label">우리가 찾은 증거</div>${r.evidenceIds.map(id=>`<button class="text-button" data-action="preview" data-id="${id}">${id} ${clues[id].title} ${icon('arrow-up-right')}</button>`).join('<br>')}</section><section class="result-section"><div class="result-label">참여를 막았던 문제</div><p>${r.problem}</p></section><section class="result-section"><div class="result-label">우리 모둠의 해결 제안</div><p class="proposal-text">${esc(r.proposal)}</p></section><div class="result-footer">단서 6개 조사 · 사연 3개 연결 완료<br>이 기록은 현재 기기에만 잠시 표시됩니다.</div></article><div class="result-actions"><button class="secondary" data-action="edit">제안 수정</button><button class="secondary" data-action="restart">처음부터</button></div><p class="note no-print">발표할 때: “우리는 이 증거에서 문제를 발견했고, 이렇게 바꾸면 좋겠다고 생각했어.”</p>`,bottom(primary('결과 크게 보기','present')))}
function render(){const views={intro,map:mapScreen,place:placeScreen,clue:clueScreen,archive:archiveScreen,reason:reasonScreen,write:writeScreen,result:resultScreen};$('#app').innerHTML=views[state.screen]();document.title=`${({intro:'시작',map:'조사 지도',place:places[state.place].name,clue:clues[state.clue].title,archive:'단서함',reason:'추리 정리',write:'해결 제안',result:'모둠의 기록'})[state.screen]} · 학교 축제 조사 수첩`}
function rerender(){const y=window.scrollY;render();window.scrollTo(0,y)}
function showDialog(content,label){$('#dialog-body').innerHTML=content;$('#dialog').setAttribute('aria-label',label);$('#dialog').showModal()}
function dialogHeader(title){return `<div class="dialog-top"><h2>${title}</h2><button class="icon-button" data-action="close" aria-label="닫기">${icon('x')}</button></div>`}
function check(){const p=state.person,a=state.selections[p];let message='',correct=false;if(a.length!==2||state.answers[p]===null)message='증거 두 개와 문제 하나를 골라 줘.';else if(!places[p].ids.every(id=>a.includes(id)))message='이 사연의 상황과 당사자의 말을 함께 보여 주는 단서 두 개를 다시 찾아봐.';else if(state.answers[p]!==p)message=hints[p];else{correct=true;state.solved[p]=true;message=explanations[p]}state.feedback={message,correct};rerender();announce(message);$('.feedback')?.scrollIntoView({block:'center',behavior:'smooth'})}
function complete(){if(!state.proposal.trim()){state.error='모두가 참여할 수 있도록 바꿀 행동이나 규칙을 한 문장 이상 적어 줘.';rerender();$('#proposal').focus();return}const p=state.proposalPerson;state.result={schemaVersion:1,activityId:'festival-rights-v1',person:places[p].person,evidenceIds:[...state.selections[p]],problem:problems[state.answers[p]],proposal:state.proposal,investigatedClueIds:[...state.read],resolvedCases:places.map((place,i)=>({person:place.person,evidenceIds:[...state.selections[i]],problem:problems[state.answers[i]]}))};go('result')}
document.addEventListener('input',event=>{if(event.target.id==='proposal'){state.proposal=event.target.value;$('#char-count').textContent=`${state.proposal.length}/300`;if(state.error){state.error='';$('#write-error')?.remove();event.target.removeAttribute('aria-invalid');event.target.setAttribute('aria-describedby','writing-note char-count')}}});
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,i=Number(b.dataset.index),id=b.dataset.id;
 switch(a){
 case 'start':go('map');break;
 case 'nav':go(b.dataset.screen);break;
 case 'back-map':go('map');break;
 case 'place':state.place=i;go('place');break;
 case 'open-clue':state.returnTo=state.screen;state.clue=id;go('clue');break;
 case 'related':state.clue=id;go('clue');break;
 case 'back-clue':go(state.returnTo);break;
 case 'mark-read':state.read.add(state.clue);announce('읽은 단서에 추가했어요.');go(state.returnTo);break;
 case 'reason':if(state.read.size!==6)return;state.expanded=true;go('reason');break;
 case 'person':state.person=i;state.feedback=null;state.expanded=true;go('reason');break;
 case 'next-person':state.person=state.solved.findIndex(v=>!v);state.expanded=true;go('reason');break;
 case 'expand':state.expanded=!state.expanded;rerender();break;
 case 'select-evidence':{const p=state.person,arr=state.selections[p];if(arr.includes(id)){state.selections[p]=arr.filter(x=>x!==id)}else if(arr.length===2){state.feedback={correct:false,message:'증거는 두 개까지 고를 수 있어. 먼저 하나를 해제해 줘.'};rerender();announce(state.feedback.message);$('.feedback')?.scrollIntoView({block:'center',behavior:'smooth'});break}else arr.push(id);state.solved[p]=false;state.feedback=null;rerender();break}
 case 'answer':state.answers[state.person]=i;state.solved[state.person]=false;state.feedback=null;rerender();break;
 case 'check':check();break;
 case 'preview':showDialog(`${dialogHeader(`${id} ${clues[id].title}`)}<div class="dialog-material">${material(id)}</div>`,'단서 원문');break;
 case 'write':if(!state.solved.every(Boolean))return;go('write');break;
 case 'back-reason':state.expanded=false;go('reason');break;
 case 'proposal-person':if(i!==state.proposalPerson&&state.proposal.trim()){showDialog(`${dialogHeader('다른 사연으로 바꿀까?')}<p>작성한 해결 제안은 지워져. 새로운 사연의 해결책을 다시 쓸 수 있어.</p><div class="actions"><button class="secondary" data-action="close">계속 쓰기</button><button class="primary" data-action="confirm-person" data-index="${i}">사연 바꾸기</button></div>`,'사연 변경 확인')}else{state.proposalPerson=i;go('write')}break;
 case 'confirm-person':$('#dialog').close();state.proposalPerson=i;state.proposal='';go('write');break;
 case 'finish':complete();break;
 case 'edit':go('write');break;
 case 'restart':showDialog(`${dialogHeader('처음부터 다시 조사할까?')}<p>지금까지 찾은 단서와 작성한 해결 제안이 사라져.</p><div class="actions"><button class="secondary" data-action="close">기록 남겨 두기</button><button class="primary" data-action="confirm-restart">다시 시작</button></div>`,'다시 시작 확인');break;
 case 'confirm-restart':$('#dialog').close();state=fresh();go('intro');break;
 case 'present':showDialog(`${dialogHeader('우리 모둠의 해결 제안')}<div class="eyebrow">${state.result.person}의 이야기</div><p style="font-size:23px;line-height:1.8;white-space:pre-wrap;overflow-wrap:anywhere">${esc(state.result.proposal)}</p>`,'발표용 해결 제안');break;
 case 'close':$('#dialog').close();break;
 case 'help':showDialog(`${dialogHeader('함께 조사하는 방법')}<div class="dialog-content-list"><div><b>01 소개 · 3분</b><p>세 친구의 사연과 조사 역할을 확인해.</p></div><div><b>02 단서 조사 · 10분</b><p>세 장소에서 단서 여섯 개를 읽어. 장소를 옮길 때 역할도 바꿔 줘.</p></div><div><b>03 추리 정리 · 7분</b><p>사연마다 증거 두 개와 문제 하나를 연결해. 틀려도 다시 생각해 볼 수 있어.</p></div><div><b>04 해결·공유 · 5분</b><p>한 사연의 해결책을 쓰고 화면을 보며 발표해.</p></div></div><hr class="thin-rule"><p>시간은 권장 시간이야. 점수나 순위는 없어.</p><p class="note">답변은 서버로 전송되지 않아. 새로고침하거나 창을 닫으면 사라져.</p>`,'활동 안내');break;
 }
});
render();
